import { NextRequest, NextResponse } from "next/server";
import { generateOpenAIChatResponse } from "@/lib/openai-chat";
import fs from "fs/promises";
import path from "path";
import pdf from "pdf-parse";

// We'll use the prompt file defined in the project structure
const PROMPT_PATH = path.join(process.cwd(), "prompts", "read_with_me", "prompt_01_book_analyzer.md");

export async function GET() {
    return NextResponse.json({ status: "alive" });
}

export async function POST(req: NextRequest) {
    try {
        const formData = await req.formData();
        const file = formData.get("pdf") as File | null;
        const bookId = formData.get("book_id") as string | null;

        if (!file || !bookId) {
            return NextResponse.json({ error: "Missing pdf file or book_id" }, { status: 400 });
        }

        // 1. Read PDF file into a buffer
        const arrayBuffer = await file.arrayBuffer();
        const buffer = Buffer.from(arrayBuffer);

        // 2. Extract text using pdf-parse
        let extractedText = "";
        try {
            const data = await pdf(buffer);
            extractedText = data.text;
        } catch (parseError) {
            console.error("PDF Parsing Error:", parseError);
            return NextResponse.json({ error: "Failed to parse PDF file" }, { status: 500 });
        }

        if (!extractedText.trim()) {
            return NextResponse.json({ error: "No text could be extracted from the PDF" }, { status: 400 });
        }

        // 3. Load the System Prompt for the Analyzer
        let systemPrompt = "";
        try {
            systemPrompt = await fs.readFile(PROMPT_PATH, "utf8");
        } catch (promptError) {
            console.error("Failed to read system prompt file:", promptError);
            return NextResponse.json({ error: "Internal Configuration Error" }, { status: 500 });
        }

        // 4. Send exactly what's requested to OpenAI
        const userMessage = `?ㅼ쓬? 異붿텧??梨??띿뒪???먮Ц?낅땲??\n\n${extractedText}`;
        const aiResponseText = await generateOpenAIChatResponse(systemPrompt, userMessage, [], true);

        // 5. Parse the returned JSON
        let bookData;
        try {
            // Claude/GPT might wrap the JSON in markdown blocks (```json ... ```)
            let jsonString = aiResponseText;
            const jsonMatch = aiResponseText.match(/```json\n([\s\S]*?)\n```/);
            if (jsonMatch && jsonMatch[1]) {
                jsonString = jsonMatch[1];
            }

            bookData = JSON.parse(jsonString);
            bookData.book_id = bookId; // Ensure the requested book_id is mapped correctly
        } catch (jsonError) {
            console.error("Failed to parse JSON response from OpenAI:", aiResponseText);
            return NextResponse.json({ error: "Failed to generate valid JSON format from text" }, { status: 500 });
        }

        // 6. Save the data to books directory
        const booksDir = path.join(process.cwd(), "data", "books");
        await fs.mkdir(booksDir, { recursive: true });

        const savePath = path.join(booksDir, `${bookId}.json`);
        await fs.writeFile(savePath, JSON.stringify(bookData, null, 2), "utf8");

        return NextResponse.json({
            success: true,
            book_data_path: `data/books/${bookId}.json`,
            book_metadata: bookData.book_metadata
        });

    } catch (error: any) {
        console.error("Analyze Book API Route Error:", error);
        return NextResponse.json({ error: error.message }, { status: 500 });
    }
}

import { NextRequest, NextResponse } from "next/server";
import { generateOpenAIChatResponse } from "@/lib/openai-chat";
import { generateTTS } from "@/lib/openai-tts";
import fs from "fs/promises";
import path from "path";

export async function POST(req: NextRequest) {
    try {
        const body = await req.json();
        const { card_id, message, conversation_history = [] } = body;

        if (!card_id || !message) {
            return NextResponse.json({ error: "Missing required fields" }, { status: 400 });
        }

        // 1. Get Card Configuration and its Prompt
        const cardsFilePath = path.join(process.cwd(), "data", "cards.json");
        const cardsData = JSON.parse(await fs.readFile(cardsFilePath, "utf8"));
        const cardConfig = cardsData.find((c: any) => c.card_id === card_id);

        if (!cardConfig) {
            return NextResponse.json({ error: "Card not found" }, { status: 404 });
        }

        let systemPrompt = "";
        let finalMessage = message;

        if (cardConfig.card_type === 'read_with_me' && body.session_state && body.book_data) {
            const { phase, currentPageIndex } = body.session_state;
            const bookData = body.book_data;
            const page = bookData.pages?.[currentPageIndex] || {};

            if (phase === 'PRE') {
                const promptPath = path.join(process.cwd(), "prompts", "read_with_me", "prompt_02_pre_reading.md");
                const template = await fs.readFile(promptPath, "utf8");
                systemPrompt = template
                    .replace("{book_metadata.title}", bookData.book_metadata.title || "")
                    .replace("{book_metadata.author}", bookData.book_metadata.author || "")
                    .replace("{book_metadata.core_values}", (bookData.book_metadata.themes || []).join(", "))
                    .replace("{pre_reading.cover.illustration_description}", bookData.pre_reading?.cover?.illustration_description || "")
                    .replace("{pre_reading.cover.tts_intro_script}", bookData.pre_reading?.cover?.tts_intro_script || "")
                    .replace("{pre_reading.cover.distancing_question}", bookData.pre_reading?.cover?.distancing_question || "")
                    .replace("{pre_reading.cover.prediction_question}", bookData.pre_reading?.cover?.prediction_question || "");

                finalMessage = `[CHILD_RESPONSE]\n${message}`;

            } else if (phase === 'DURING_DIALOGIC') {
                const promptPath = path.join(process.cwd(), "prompts", "read_with_me", "prompt_03_during_dialogic.md");
                const template = await fs.readFile(promptPath, "utf8");

                // Simple template replacement for dialogic reading data
                systemPrompt = template
                    .replace("{page.page_number}", page.page_number || "")
                    .replace("{page.illustration_description}", page.illustration_description || "")
                    .replace("{page.text}", page.text || "")
                    .replace("{page.tts_read_script}", page.tts_read_script || "")
                    .replace("{page.key_vocabulary[0].word}", page.key_vocabulary?.[0]?.word || "")
                    .replace("{page.key_vocabulary[0].easy_definition}", page.key_vocabulary?.[0]?.easy_definition || "")
                    .replace("{page.key_vocabulary[0].phonics_play_hint}", page.key_vocabulary?.[0]?.phonics_play_hint || "")
                    .replace("{page.crowd_questions[0].question_type}", page.crowd_questions?.[0]?.question_type || "")
                    .replace("{page.crowd_questions[0].question}", page.crowd_questions?.[0]?.question || "")
                    .replace("{page.crowd_questions[0].scaffolding.hint_if_wrong}", page.crowd_questions?.[0]?.scaffolding?.hint_if_wrong || "")
                    .replace("{page.crowd_questions[0].scaffolding.simplified_version}", page.crowd_questions?.[0]?.scaffolding?.simplified_version || "")
                    .replace("{page.crowd_questions[0].scaffolding.deeper_question_if_correct}", page.crowd_questions?.[0]?.scaffolding?.deeper_question_if_correct || "")
                    .replace("{page.crowd_questions[1].question_type}", page.crowd_questions?.[1]?.question_type || "")
                    .replace("{page.crowd_questions[1].question}", page.crowd_questions?.[1]?.question || "")
                    .replace("{page.crowd_questions[1].scaffolding.hint_if_wrong}", page.crowd_questions?.[1]?.scaffolding?.hint_if_wrong || "")
                    .replace("{page.crowd_questions[1].scaffolding.simplified_version}", page.crowd_questions?.[1]?.scaffolding?.simplified_version || "")
                    .replace("{page.crowd_questions[1].scaffolding.deeper_question_if_correct}", page.crowd_questions?.[1]?.scaffolding?.deeper_question_if_correct || "");

                finalMessage = `[CHILD_RESPONSE]\n${message}`;

            } else if (phase === 'POST') {
                const promptPath = path.join(process.cwd(), "prompts", "read_with_me", "prompt_05_post_reading.md");
                const template = await fs.readFile(promptPath, "utf8");
                systemPrompt = template
                    .replace("{post_reading.wrap_up.summary_question}", bookData.post_reading?.wrap_up?.summary_question || "")
                    .replace("{post_reading.wrap_up.favorite_part_question}", bookData.post_reading?.wrap_up?.favorite_part_question || "")
                    .replace("{post_reading.wrap_up.closing_statement}", bookData.post_reading?.wrap_up?.closing_statement || "");

                finalMessage = `[CHILD_RESPONSE]\n${message}`;
            }

            // Append strict JSON output instructions
            systemPrompt += `\n\n[RESPONSE FORMAT INSTRUCTIONS]
You must respond in strict JSON format. Do NOT wrap it in markdown block quotes. Use the following schema:
{
  "response": "Your spoken dialogue here",
  "next_state": {
    "phase": "PRE" | "DURING_DIALOGIC" | "POST" | "END",
    "currentPageIndex": number
  }
}
Based on the current conversation progress, determine the next state. 
- If staying on current page/phase, return the same phase and currentPageIndex.
- If moving to reading, change phase to "DURING_DIALOGIC" and currentPageIndex to 0.
- If moving to next page, keep "DURING_DIALOGIC" and increment currentPageIndex.
- If last page is done, change phase to "POST".
- If POST reading is done, change phase to "END".
Current state is: phase="${phase}", currentPageIndex=${currentPageIndex}, totalPages=${bookData.book_metadata.total_pages}.
`;

        } else {
            // Fallback to standard general prompt
            if (cardConfig.prompt_file) {
                const promptPath = path.join(process.cwd(), cardConfig.prompt_file);
                systemPrompt = await fs.readFile(promptPath, "utf8");
            }
        }

        // 2. Get OpenAI Text Response
        const isJsonMode = cardConfig.card_type === 'read_with_me';
        const aiResponseRaw = await generateOpenAIChatResponse(systemPrompt, finalMessage, conversation_history, isJsonMode);

        let aiResponseText = aiResponseRaw;
        let newSessionState = null;

        if (isJsonMode) {
            try {
                const parsed = JSON.parse(aiResponseRaw);
                aiResponseText = parsed.response || "?묐떟???뚯떛?????놁뒿?덈떎.";
                newSessionState = parsed.next_state;
            } catch (e) {
                console.error("Failed to parse JSON response:", aiResponseRaw);
                aiResponseText = "?묐떟 ?ㅻ쪟媛 諛쒖깮?덉뒿?덈떎.";
            }
        }

        let audioBase64 = null;
        try {
            // 3. Optional: Generate TTS Audio for the response
            const audioBuffer = await generateTTS(aiResponseText, cardConfig.voice_openai);
            audioBase64 = `data:audio/mp3;base64,${audioBuffer.toString('base64')}`;
        } catch (ttsErr) {
            console.error("TTS generation failed, returning text only.", ttsErr);
        }

        return NextResponse.json({
            response: aiResponseText,
            audio_url: audioBase64,
            ...(newSessionState && { session_state: newSessionState })
        });

    } catch (error: any) {
        console.error("Chat API Route Error:", error);
        return NextResponse.json({ error: error.message }, { status: 500 });
    }
}
